def extract_json(reply: str) -> str:
    """Return the first balanced {...} substring from reply."""
    start = reply.index('{')
    depth = 0
    for i in range(start, len(reply)):
        ch = reply[i]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return reply[start:i + 1]
    raise ValueError("no balanced JSON object found")

print(extract_json('Sure! Here: {"ok": true, "n": {"x": 1}} -- done'))
